def _bind_names(target, out: set) -> None:
    """Names an assignment target BINDS -- not names it merely reads through.

    `os.environ["X"] = v` and `obj.attr = v` mutate the object a name already points at;
    the name still refers to the same module afterwards. `ast.walk()` over the target
    cannot tell those from `os = v`, and it did not: it reported a rebind of `os` for
    every module-level `os.environ[...] = ...`, which is the form CLAUDE.md *requires*
    tests to use to force ECC_HOOK_PROFILE. Measured on this tree, all four files the
    gate flagged were of that shape -- four false positives, zero true ones.

    So Subscript and Attribute are not descended into. Tuple, List and Starred are,
    because `a, b = ...` and `*rest, = ...` really do bind their elements.
    """
    if isinstance(target, ast.Name):
        out.add(target.id)
    elif isinstance(target, (ast.Tuple, ast.List)):
        for element in target.elts:
            _bind_names(element, out)
    elif isinstance(target, ast.Starred):
        _bind_names(target.value, out)


# Types that actually catch an ImportError. `Exception` is here because it genuinely
# does, and because the shipped `.claude/hooks/iron-law-gate.py:113` uses exactly that
# form -- "a gate must never crash on an optional import". Restricting this to the two
# import errors was tried first and reported that real file as a shadow.
_FALLBACK_EXCEPTIONS = ("ImportError", "ModuleNotFoundError", "Exception", "BaseException")


def _catches_import_error(handler) -> bool:
    """True when this handler catches a type an import failure would raise.

    `except ValueError:` returns False: it cannot catch an ImportError, so a rebind under
    it is not the fallback idiom. A bare `except:` returns False too -- it does catch the
    import, but it is rare enough that requiring a named type costs nothing and keeps the
    exemption legible. Widening this to every handler is how a gate stops binding.
    """
    node = handler.type
    if node is None:
        return False
    for part in (node.elts if isinstance(node, ast.Tuple) else [node]):
        if isinstance(part, ast.Name) and part.id in _FALLBACK_EXCEPTIONS:
            return True
        if isinstance(part, ast.Attribute) and part.attr in _FALLBACK_EXCEPTIONS:
            return True
    return False


def _fallback_names(try_node) -> frozenset:
    """Names the optional-import idiom may rebind inside THIS try's handlers.

        try:
            import reflection as _reflection
        except ImportError:
            _reflection = None

    Returned so the caller can exempt the BINDING SITES inside those handlers -- never
    the name across the file. Subtracting a name set at the end of `shadowed` instead
    lets one fallback launder every later rebind of that name, including the exact
    `import html` / `html = <str>` defect this gate was built for. Measured before that
    was fixed: real iron-law-gate.py plus a trailing `_reflection = 'a str'` reported
    clean.

    Only direct statements of the try body count, and only when a handler actually
    catches an import failure. A rebind in the try BODY is not a fallback either -- it
    runs unconditionally.
    """
    if not any(_catches_import_error(h) for h in try_node.handlers):
        return frozenset()
    # `except Exception:` implies "the import failed" ONLY when the body can raise
    # nothing else. Let the body do other fallible work and the handler runs with the
    # import having SUCCEEDED, so its rebind is live -- the exact `import html` /
    # `html = <str>` defect this gate exists for. Measured: `try: import yaml; CONFIG =
    # yaml.safe_load(open(...)) / except Exception: yaml = None` reported clean until
    # this guard existed. Narrowing on the BODY rather than on the exception type is what
    # keeps iron-law-gate.py exempt, since its body is a single import.
    if any(not isinstance(st, (ast.Import, ast.ImportFrom, ast.Pass))
           for st in try_node.body):
        return frozenset()
    names = set()
    for statement in try_node.body:
        if isinstance(statement, ast.Import):
            for alias in statement.names:
                names.add(alias.asname or alias.name.split('.')[0])
        elif isinstance(statement, ast.ImportFrom):
            for alias in statement.names:
                names.add(alias.asname or alias.name)
    return frozenset(names)


